        if (shouldResend(reason)) this.handledKeys.delete(row.key); // 다음 회차에 같은 키로 다시 온다
        continue;
      }
      const d: DeliveredAlert = {
        runId,
        orderNo: n.orderNo,
        customerId: n.customerId,
        kind: n.kind,
        phone: customer.phone,
        receiptId: receipt.receiptId ?? "",
      };
      this.log.append(d);
      result.delivered.push(d);
    }
    return result;
  }
}
